package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen2Test {

    @Test
    public void testEquals_SameInstance() {
        Complex c = new Complex(1.0, 2.0);
        Assert.assertTrue("Equality with the same instance should return true", c.equals(c));
    }

    @Test
    public void testEquals_DifferentType() {
        Complex c = new Complex(1.0, 2.0);
        Assert.assertFalse("Equality with a different object type should return false", c.equals("Not a Complex"));
        Assert.assertFalse("Equality with null should return false", c.equals(null));
    }

    @Test
    public void testEquals_NaN_BothNaN() {
        // Since we cannot directly set isNaN via constructor based on the provided API, 
        // we assume a way to obtain a NaN complex (usually via Double.NaN)
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(Double.NaN, Double.NaN);

        // Based on the code: if (c.isNaN) { return isNaN; }
        // This implies if both are NaN, it returns true.
        Assert.assertTrue("Two NaN complex numbers should be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_NotNaN() {
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(1.0, 2.0);
        Assert.assertFalse("A NaN complex should not equal a non-NaN complex", c1.equals(c2));
        Assert.assertFalse("A non-NaN complex should not equal a NaN complex", c2.equals(c1));
    }

    @Test
    public void testEquals_SameValues() {
        Complex c1 = new Complex(1.5, -3.0);
        Complex c2 = new Complex(1.5, -3.0);
        Assert.assertTrue("Complex numbers with same real and imaginary parts should be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentReal() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.1, 2.0);
        Assert.assertFalse("Complex numbers with different real parts should not be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentImaginary() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.1);
        Assert.assertFalse("Complex numbers with different imaginary parts should not be equal", c1.equals(c2));
    }

    @Test
    public void testEquals_EdgeCases() {
        Complex c1 = new Complex(0.0, 0.0);
        Complex c2 = new Complex(0.0, 0.0);
        Assert.assertTrue("Zero complex numbers should be equal", c1.equals(c2));

        Complex c3 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex c4 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Assert.assertTrue("Infinite complex numbers should be equal", c3.equals(c4));
    }
}
